import unittest
from candidate import triples_sum_to_zero

class TestTriplesSumToZero(unittest.TestCase):
    def test_triples_sum_to_zero_normal_case_returns_false(self):
        self.assertFalse(triples_sum_to_zero([1, 3, 5, 0]))

    def test_triples_sum_to_zero_normal_case_returns_true(self):
        self.assertTrue(triples_sum_to_zero([1, 3, -2, 1]))

    def test_triples_sum_to_zero_another_normal_case_returns_false(self):
        self.assertFalse(triples_sum_to_zero([1, 2, 3, 7]))

    def test_triples_sum_to_zero_exact_six_elements_returns_true(self):
        self.assertTrue(triples_sum_to_zero([2, 4, -5, 3, 9, 7]))

    def test_triples_sum_to_zero_single_element_returns_false(self):
        self.assertFalse(triples_sum_to_zero([1]))

    def test_triples_sum_to_zero_empty_list_returns_false(self):
        self.assertFalse(triples_sum_to_zero([]))

    def test_triples_sum_to_zero_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            triples_sum_to_zero(None)

    def test_triples_sum_to_zero_invalid_type_raises_type_error(self):
        with self.assertRaises(TypeError):
            triples_sum_to_zero(5)

    def test_triples_sum_to_zero_triple_zero_values_returns_true(self):
        self.assertTrue(triples_sum_to_zero([0, 0, 0]))
